mapper.select:
select t.total, t.name from (select count(a.manufacturer_id) total, m.name from asset a left join asset_manufacturer m on a.manufacturer_id = m.id where a.manufacturer_id is not null and a.is_del = 1 and a.org_id in
#{id}
group by m.name) t order by total desc

select count(a.desk) total, m.name, m.code as id from asset a left join asset_mode m on a.desk = m.code where a.desk is not null and a.is_del = 1 and m.code is not null and a.org_id in
#{id}
group by m.name, m.code order by m.code

select t.total, o.title name from ( select count(org_id) total, org_id from asset a where a.is_del = 1 and a.org_id in
#{id}
group by org_id) t left join sys_org o on t.org_id = o.id order by total desc

select a.NAME assetName, a.ip assetIp, a.ONLINE_TIME, a.IPMI_IP, a.OPERATION_SYSTEM, a.ASSET_CODE, m.NAME manufacturer, o.TITLE orgName, d.NAME assetMode, DECODE(a.STATUS, 1, '在线', 0, '离线', '未知') statusStr from asset a left join sys_org o on a.org_id = o.id left join ASSET_MANUFACTURER m on a.MANUFACTURER_ID = m.ID left join ASSET_MODE d on a.DESK = d.CODE where a.IS_DEL = 1 and rownum < 20000
and a.org_id = #{orgId}
and a.watch = #{watch}
and a.manufacturer_id = #{manufacturerId}
and a.org_id in
#{id}
and REGEXP_LIKE(a.name, #{name})
and REGEXP_LIKE(a.ip, #{ip})
and a.desk = #{desk}
and to_char(a.downline_time,'yyyy-MM-dd') >= (select concat(extract(year from sysdate)-1,'-'||to_char(sysdate,'MM-dd')) endTime from dual)

select t.desk code, t.total total, m.name
from (select desk, count(*) total from asset where is_del = 1

    and manufacturer_id = #{map.manufacturerId}


    and MONITOR = #{map.monitorStatus}


    and STATUS = #{map.status}


    and COLLECTION_TYPE = #{map.collectionType}


    and DOWNLINE_TIME < #{map.today}


    and DOWNLINE_TIME >= #{map.today}


    and org_id = #{map.orgId}


    and name like concat(concat('%', #{map.name}),'%')


    and desk = #{map.desk}


    and watch = #{map.watch}


    and ip = #{map.ip} or ip2 = #{map.ip} or IPMI_IP = #{map.ip}


    and org_id in


            #{id}


            #{id}



group by desk) t
left join asset_mode m on t.desk = m.code
where m.name is not null

select t.asset_image code, t.total, m.model name
from (select asset_image, count(*) total from asset where is_del = 1

    and org_id = #{map.orgId}


    and manufacturer_id = #{map.manufacturerId}


    and DOWNLINE_TIME < #{map.today}


    and DOWNLINE_TIME >= #{map.today}


    and MONITOR = #{map.monitorStatus}


    and STATUS = #{map.status}


    and COLLECTION_TYPE = #{map.collectionType}


    and name like concat(concat('%', #{map.name}),'%')


    and desk = #{map.desk}


    and watch = #{map.watch}


    and ip = #{map.ip} or ip2 = #{map.ip} or IPMI_IP = #{map.ip}


    and org_id in


            #{id}


            #{id}



group by asset_image) t
left join asset_model m on t.asset_image = m.model
where m.model is not null
order by total desc

select id, name, org_id from asset where is_del = 1

    and org_id in

        #{id}



    and id in

        #{id}



    and desk in

        #{id}



    and service_type_id = #{serviceTypeId}


    and desk = #{assetDesk}


    and asset_image = #{assetImage}

SELECT * FROM (SELECT a.NAME assetName, a.ip assetIp, l.port_index, l.link_asset_name, l.link_asset_ip, l.link_port, DECODE(a.ASSET_MODE, 42, '路由器', 201, '交换机', '未知') assetModeStr FROM ASSET_LINK_ASSET l LEFT JOIN ASSET a ON l.ASSET_ID = a.ID WHERE a.ASSET_MODE IN (42, 201)
AND a.ORG_ID = #{orgId}
AND a.ID in
#{id}
order by a.name, to_number(l.port_index_rank)) t WHERE t.assetName is not null
